command:
if (!game.user.isGM) return ui.notifications.warn('Quick Level Up Unit(s) is GM-only.');

const STAT_LABELS = {
  hp: 'HP', mgt: 'MGT', agi: 'AGI', tqn: 'TQN', wit: 'WIT', cha: 'CHA', def: 'DEF', res: 'RES'
};
const MAX_LEVEL = 30;

const units = (canvas.tokens?.controlled ?? []).filter(token => token.actor?.type === 'Character');
if (!units.length) return ui.notifications.warn('Select one or more units first.');

const levels = await foundry.applications.api.DialogV2.wait({
  window: { title: 'Quick Level Up Unit(s)' },
  classes: ['emblem-rpg', 'dialog-editor'],
  position: { width: 400 },
  content: `
    <div class="ed-container">
      <div class="ed-section ed-section--highlight">
        <p class="ed-description">${units.length} unit${units.length === 1 ? '' : 's'} selected.
          Each level is rolled silently; the growths are reported in the console only.</p>
      </div>
      <div class="ed-section">
        <label class="ed-label" for="emblem-quick-levels">Levels to gain</label>
        <input id="emblem-quick-levels" class="ed-input" type="number" name="levels" min="1" max="${MAX_LEVEL}" step="1" value="1" autofocus />
      </div>
    </div>`,
  buttons: [
    {
      action: 'level',
      label: 'Level Up',
      icon: 'fas fa-angles-up',
      default: true,
      callback: (event, button) => Number(button.form.elements.levels.value)
    },
    { action: 'cancel', label: 'Cancel', callback: () => null }
  ],
  rejectClose: false
});

if (typeof levels !== 'number' || !Number.isFinite(levels) || levels < 1) return;
const rounds = Math.floor(levels);

const summary = [];
const growths = [];
const failures = [];

for (const token of units) {
  const actor = token.actor;
  const from = Number(actor.system.progression?.level) || 1;
  let reached = from;
  for (let round = 0; round < rounds; round += 1) {
    if (reached >= MAX_LEVEL) break;
    const result = await game.emblemRpg.api.character.progression.levelUp({ actorUuid: actor.uuid, quiet: true });
    if (!result.ok) {
      failures.push({ unit: actor.name, atLevel: reached, code: result.code });
      break;
    }
    reached = Number(result.data.level) || reached;
    for (const [key, stat] of Object.entries(result.data.stats ?? {})) {
      if (!stat.increased) continue;
      growths.push({
        unit: actor.name,
        level: reached,
        stat: STAT_LABELS[key] ?? key,
        from: stat.oldValue,
        to: stat.newValue,
        roll: `${stat.roll} vs ${stat.growthChance}`
      });
    }
  }
  summary.push({ unit: actor.name, level: `${from} → ${reached}`, gained: reached - from });
}

console.group(`emblem-rpg | Quick Level Up Unit(s) — ${rounds} level(s) requested on ${units.length} unit(s)`);
console.table(summary);
if (growths.length) console.table(growths);
else console.log('No stat grew on any roll.');
if (failures.length) console.table(failures);
console.groupEnd();

const gained = summary.reduce((total, row) => total + row.gained, 0);
if (failures.length) ui.notifications.error(`Gained ${gained} level(s); ${failures.length} refused, see console.`);
else ui.notifications.info(`Gained ${gained} level(s) quietly — growths in the console.`);
